examples.code:
set budget 75
if {$budget >= 90} {
    set plan "扩展包"
} elseif {$budget >= 60} {
    set plan "标准包"
} elseif {$budget >= 30} {
    set plan "基础包"
} else {
    set plan "暂缓采购"
}
puts $plan

set status "confirmed"
set people 2
if {$status eq "confirmed" && $people > 0} {
    puts "可以制作名牌"
} else {
    puts "等待有效报名"
}

exercises.solution:
set subtotal 80
set threshold 80
if {$subtotal >= $threshold} {
    set shipping 0
} else {
    set shipping 6
}
puts "运费：$shipping"

set value 35
if {$value < 10} {
    set label "偏低"
} elseif {$value <= 30} {
    set label "正常"
} else {
    set label "偏高"
}
puts $label

set status "pending"
set people 0
set code "01"
if {$status eq "confirmed" && $people > 0} {
    set action "制作名牌"
} else {
    set action "核实报名"
}
set sameCode [expr {$code eq "1"}]
puts $action
puts $sameCode
